const state = {
  route: location.hash.slice(1) || 'home',
  theme: localStorage.getItem('ss-theme') || 'light',
  lang: localStorage.getItem('ss-lang') || 'ar',
  user: JSON.parse(localStorage.getItem('ss-user') || 'null'),
  selectedExchange: null,
  notifications: 0,
  assistantOpen: false,
  assistantBusy: false,
  skipProfileFetch: false,
  skipAdminFetch: false,
  recoveryToken: sessionStorage.getItem('ss-recovery-token') || '',
};

const users = [];
const skills = [];
const exchanges = [];
const notifications = [];
const jobs = [];
const ads = [];
const adminCache = {analytics:null, users:[], reports:[], exchanges:[], reviews:[], ads:[], jobs:[], skills:[], categories:[], actions:[], settings:{}};
let messages = [];
let realtimeSocket = null;

function t(ar,en){ return state.lang === 'ar' ? ar : en; }
function esc(value){ return String(value ?? '').replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m])); }
function formatDate(value){ try{return new Date(value).toLocaleDateString(state.lang==='ar'?'ar-EG':'en-US',{day:'numeric',month:'short',year:'numeric'});}catch{return value||'';} }
function formatTime(value){ try{return new Date(value).toLocaleTimeString(state.lang==='ar'?'ar-EG':'en-US',{hour:'2-digit',minute:'2-digit'});}catch{return value||'';} }
function initials(name=''){return name.trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase() || '?';}
function userBy(id){return users.find(u=>String(u.id)===String(id));}
function exchangeBy(id){return exchanges.find(x=>String(x.id)===String(id));}
function currentUserId(){return state.user?.id || null;}
function routeBase(){return state.route.split('/')[0];}
function isAdmin(){return new Set(['SUPER_ADMIN','ADMIN','MODERATOR','SUPPORT','FINANCE_MANAGER','ADS_MANAGER']).has(state.user?.role);}

