function avatar(user, cls=''){ const u=user||{name:'?',avatar_url:''}; return `<div class="avatar ${cls}">${u.avatar_url?`<img src="${esc(u.avatar_url)}" alt="">`:esc(initials(u.name))}</div>`; }
function stars(r){const rating=Math.round(Number(r||0));return `<span class="stars" aria-label="${Number(r||0)} / 5">${[0,1,2,3,4].map(i=>i<rating?icon('star',14):'<span class="star-empty">☆</span>').join('')}</span>`;}
function statusTag(s){
  const map={pending:['قيد الانتظار','warning'],accepted:['مقبول','primary'],scheduled:['مجدول','primary'],in_progress:['قيد التنفيذ','primary'],completed:['مكتمل','success'],rejected:['مرفوض','danger'],cancelled:['ملغي','danger'],disputed:['متنازع عليه','danger'],active:['نشط','success'],suspended:['موقوف','warning'],banned:['محظور','danger'],open:['مفتوح','warning'],investigating:['قيد التحقيق','primary'],resolved:['تمت المعالجة','success'],dismissed:['مرفوض','muted'],published:['منشور','success'],hidden:['مخفي','danger'],disabled:['متوقف','muted'],closed:['مغلق','muted']};
  const x=map[s]||[s,'muted']; return `<span class="tag ${x[1]}">${esc(x[0])}</span>`;
}
function toast(msg,type=''){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=msg;document.getElementById('toast-root').appendChild(el);setTimeout(()=>el.remove(),2800);}
function showModal(content,size='md'){document.getElementById('modal-root').innerHTML=`<div class="modal-backdrop" onclick="if(event.target===this)closeModal()"><div class="modal ${size}">${content}</div></div>`;document.body.classList.add('modal-open');}
function closeModal(){document.getElementById('modal-root').innerHTML='';document.body.classList.remove('modal-open');}
function go(route){location.hash=route;}
function toggleTheme(){state.theme=state.theme==='dark'?'light':'dark';localStorage.setItem('ss-theme',state.theme);render();}
function toggleLang(){state.lang=state.lang==='ar'?'en':'ar';localStorage.setItem('ss-lang',state.lang);render();}

const authToken=()=>localStorage.getItem('ss-token')||'';
const refreshToken=()=>localStorage.getItem('ss-refresh')||'';
function saveSession(session,user){if(session?.access_token)localStorage.setItem('ss-token',session.access_token);if(session?.refresh_token)localStorage.setItem('ss-refresh',session.refresh_token);if(user){state.user=user;localStorage.setItem('ss-user',JSON.stringify(user));}}
async function refreshSession(){
  const token=refreshToken(); if(!token) return false;
  const res=await fetch(API_BASE+'/auth/refresh',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({refresh_token:token})});
  const data=await res.json().catch(()=>({success:false}));
  if(!res.ok||data.success===false)return false;
  saveSession(data.data.session,data.data.user);
  connectRealtime();
  return true;
}
async function api(path, options={}, retry=true){
  const headers={'Content-Type':'application/json',...(options.headers||{})}; if(authToken())headers.Authorization=`Bearer ${authToken()}`;
  const res=await fetch(API_BASE+path,{...options,headers});
  if(res.status===401 && retry && refreshToken() && !String(path).includes('/auth/refresh')){
    if(await refreshSession()) return api(path,options,false);
  }
  const data=await res.json().catch(()=>({success:false,message:'Invalid server response'}));
  if(!res.ok||data.success===false){const e=new Error(data.message||'Request failed');e.status=res.status;e.code=data.code;throw e;}
  return data.data ?? data;
}

function normalizeUser(u){return {...u,avatar:(u.name||'?').trim().charAt(0)||'?',verified:!!u.is_verified,rating:Number(u.rating||0),exchanges:Number(u.exchanges||0),offers:u.offers||[],needs:u.needs||[]};}
function normalizeSkill(s){return {...s,id:s.id,name:s.name,cat:s.category||'Other',users:Number(s.users||0),requests:Number(s.requests||0)};}
function normalizeExchange(e){return {id:e.id,a:e.sender_id,b:e.receiver_id,offer:e.offered_skill,request:e.requested_skill,type:e.deal_type,status:e.status,created:e.created_at,updated:e.updated_at||e.created_at,message:e.message||''};}
function normalizeMessage(m){return {id:m.id,exchange:m.exchange_id,from:m.sender_id,body:m.body,time:m.sent_at};}
function normalizeJob(j){return {...j,id:j.id};}

async function hydrateBackend(){
  try{
    const [us,sk,adData,jobData]=await Promise.all([api('/users'),api('/skills'),api('/ads'),api('/jobs')]);
    users.splice(0,users.length,...us.map(normalizeUser));
    skills.splice(0,skills.length,...sk.map(normalizeSkill));
    ads.splice(0,ads.length,...adData);
    jobs.splice(0,jobs.length,...jobData.map(normalizeJob));
    if(authToken()){
      try{state.user=await api('/auth/me').then(x=>x.user);localStorage.setItem('ss-user',JSON.stringify(state.user));}
      catch{localStorage.removeItem('ss-token');localStorage.removeItem('ss-user');state.user=null;}
      if(state.user){
        const [ex,ns]=await Promise.all([api('/exchanges'),api('/notifications')]);
        exchanges.splice(0,exchanges.length,...ex.map(normalizeExchange));
        notifications.splice(0,notifications.length,...ns.map(n=>({...n,title:n.title,body:n.body,time:n.created_at,unread:!n.is_read})));
        state.notifications=notifications.filter(n=>n.unread).length;
      }
    }
  }catch(e){
    if(!navigator.onLine)toast(t('أنت غير متصل حاليًا','You are offline'),'error');
    else console.warn(e);
  }
  render();
}

